(() => {
  const s = { variant:'a', view:'home', items:[], cursor:'', total:0, countries:[], selected:null, queue:[], saved:[], query:'', country:'', tag:'', request:0, loading:false, error:'', more:false, timer:0 };
  const $ = id => document.getElementById(id);
  const surface = $('surface');
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tags = x => (x.tags || '').split(',').map(t => t.trim()).filter(Boolean);
  const country = x => {const label=x.countrycode?new Intl.DisplayNames(['ru'],{type:'region'}).of(x.countrycode.toUpperCase()):x.country;return [x.state,label].filter(Boolean).join(' · ')||'Место не указано';};
  const current = () => s.selected || s.items[0] || null;
  const icon = x => x.stationArtwork || x.favicon || '';
  const art = x => icon(x) ? `<img src="${esc(icon(x))}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="cover-fallback" hidden>${esc((x.name||'R')[0])}</span>` : `<span class="cover-fallback">${esc((x.name||'R')[0])}</span>`;
  const rows = (items, cls='') => items.map(x => `<article class="station-row ${cls} ${current()?.stationuuid===x.stationuuid?'is-selected':''}"><button class="station-select" data-select="${esc(x.stationuuid)}" aria-label="Выбрать ${esc(x.name)}"><span class="artwork">${art(x)}</span><span class="station-copy"><strong>${esc(x.name)}</strong><small>${esc(country(x))}</small><span class="tagline">${esc(tags(x).slice(0,3).join(' · ')||'Радио')}</span></span><span class="select-glyph" aria-hidden="true">${current()?.stationuuid===x.stationuuid?'✓':'↗'}</span></button></article>`).join('');
  const options = () => { const names = new Intl.DisplayNames(['ru'],{type:'region'}); const codes=new Map(s.items.filter(x=>x.countrycode).map(x=>[x.country,x.countrycode.toUpperCase()])); const aliases={'The United Kingdom Of Great Britain And Northern Ireland':'GB','The United States Of America':'US','Islamic Republic Of Iran':'IR','The Netherlands':'NL','The Russian Federation':'RU','The Republic Of Korea':'KR','Türkiye':'TR','Taiwan, Republic Of China':'TW','Coted Ivoire':'CI'}; return s.countries.map(c=>{const code=codes.get(c)||aliases[c];const label=code?names.of(code):c.replace(/^The /,'').replace(/ Of /g,' of ');return `<option value="${esc(c)}" ${s.country===c?'selected':''}>${esc(label||c)}</option>`}).join(''); };
  function search(){return `<section class="browse-panel"><div class="panel-heading"><div><p class="eyebrow">КАТАЛОГ</p><h2>Эфиры для открытия</h2></div><span class="result-total">${s.total.toLocaleString('ru-RU')}</span></div><form class="search-form" id="search-form"><label class="sr-only" for="station-search">Поиск по названию и стилю</label><input id="station-search" name="q" value="${esc(s.query)}" placeholder="Название, страна или звучание"><button class="icon-button" aria-label="Искать">⌕</button></form><div class="filter-line"><label class="sr-only" for="country-filter">Страна</label><select id="country-filter"><option value="">Все страны</option>${options()}</select><label class="sr-only" for="category-filter">Направление</label><select id="category-filter"><option value="">Все направления</option>${['jazz|Джаз','rock|Рок','electronic|Электроника','classical|Классика','ambient|Спокойное'].map(x=>{const [v,l]=x.split('|');return `<option value="${v}" ${s.tag===v?'selected':''}>${l}</option>`}).join('')}</select></div>${!s.loading&&!s.error&&s.items.length===0?`<div class="empty-search"><p>Эфиры не найдены</p><button class="text-button" data-action="reset-search">Сбросить поиск</button></div>`:`<div class="station-list">${rows(s.items)}</div>`}${s.error?`<p class="error-box" role="alert">${esc(s.error)} <button class="text-button" data-action="retry">Повторить</button></p>`:''}${s.loading?'<p class="loading-note">Загружаем каталог…</p>':''}${s.cursor?'<button class="button more-results" data-action="more-results">Загрузить ещё эфиры</button>':''}</section>`;}
  const genres = () => `<div class="category-grid">${[['jazz','Ночной джаз','01'],['rock','Гитары и драйв','02'],['electronic','Электронные миры','03'],['ambient','Тихие частоты','04']].map(([v,l,n])=>`<button class="category-tile tile-${v}" data-tag="${v}"><span>${n}</span><strong>${l}</strong><small>Открыть эфиры ↗</small></button>`).join('')}</div>`;
  const selectedCard = () => {const x=current();return x?`<section class="selected-inline"><span class="artwork">${art(x)}</span><div><small>ВЫБРАННЫЙ ЭФИР</small><strong>${esc(x.name)}</strong><span>${esc(country(x))}</span></div><button class="button primary-button" data-action="enter-feed">Включай</button></section>`:'';};
  const globe = `<a class="globe-door" href="http://127.0.0.1:5184/?calm=1" target="_blank" rel="noopener"><span class="globe-orb">◎</span><span><strong>Открыть глобус</strong><small>Исследовать места в приложении</small></span><span>↗</span></a>`;
  const masthead = `<header class="masthead"><a class="wordmark" href="#" data-dest="home"><span class="mark">R</span>RadioAtlas</a><span class="edition">КАРТА ЗВУКА</span>${globe}</header>`;
  function homeA(){return `${masthead}<div class="home-intro"><h1>Новый эфир рядом.</h1>${selectedCard()}</div><div class="a-home-grid"><div class="discovery-column"><section class="first-choices"><div class="section-title"><h2>Начни с находки</h2><button class="text-button" data-action="refresh">Обновить ↻</button></div><div class="station-list featured-list">${rows(s.items.slice(0,4))}</div></section><section class="directions-section"><div class="section-title"><div><p class="eyebrow">ПО ЗВУЧАНИЮ</p><h2>Куда настроиться?</h2></div><span class="section-note">Реальные стили из каталога</span></div>${genres()}</section><section class="countries-section"><div class="section-title"><div><p class="eyebrow">ПО МЕСТУ</p><h2>Поверни глобус</h2></div></div><p class="editorial-note">От точки на карте — к источнику музыки.</p>${globe}</section>${search()}</div><aside class="a-sidebar"><section class="side-now"><p class="eyebrow">ВЫБРАННЫЙ ЭФИР</p>${current()?`<div class="side-station"><span class="artwork">${art(current())}</span><div><strong>${esc(current().name)}</strong><small>${esc(country(current()))}</small></div></div>`:''}<button class="text-button" data-dest="feed">Перейти в Ленту →</button><div class="side-actions"><button data-action="save">♡ Сохранить</button><button data-action="queue">＋ В очередь</button></div>${s.queue.length?`<p class="queue-note">Очередь макета: ${s.queue.map(x=>esc(x.name)).join(' · ')}</p>`:''}</section></aside></div>`;}
  function homeB(){return `${masthead}<div class="b-home-grid"><div class="b-home-primary"><section class="audition-stage">${selectedCard()}<div class="stage-stepper"><button class="button secondary-button" data-action="prev">← Предыдущий</button><button class="button primary-button" data-action="next">Следующий →</button></div></section><section class="b-bottom-links"><div><p class="eyebrow">ИССЛЕДУЙ СВОБОДНО</p><h2>По настроению<br>или по месту</h2></div>${genres()}${globe}</section></div><section class="b-browser">${search()}</section></div>`;}
  function feed(){const x=current();return `${masthead}<div class="feed-layout"><section class="feed-stage"><div class="feed-stage-top"><p class="eyebrow">ЛЕНТА · ВЫБРАННЫЙ ЭФИР</p><button class="icon-button" data-action="more" aria-label="Ещё действия" aria-expanded="${s.more}">•••</button></div><div class="feed-identity"><span class="feed-art">${x?art(x):''}</span><div><p class="eyebrow">${esc(country(x||{}))}</p><h1>${esc(x?.name||'Выбери эфир')}</h1><div class="tag-cloud">${tags(x||{}).slice(0,4).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div></div><div class="feed-transport"><button class="button secondary-button" data-action="prev">↑ Предыдущий</button><button class="button listen-button" data-action="listen">▶ Слушать</button><button class="button primary-button" data-action="next">Следующий ↓</button></div><div class="feed-actions"><button data-action="save">♡ Сохранить станцию</button><button data-action="queue">＋ В очередь</button><button data-dest="lira">✳ Лира</button></div>${s.more?`<div class="more-menu"><button data-action="record">Записать эфир</button><a href="http://127.0.0.1:5184/?calm=1" target="_blank" rel="noopener">Открыть Глобус приложения ↗</a></div>`:''}</section><aside class="feed-neighbors"><div class="section-title"><div><p class="eyebrow">ДРУГОЙ ИСТОЧНИК</p><h2>Слушай дальше</h2></div></div><div class="station-list">${rows(s.items.filter(y=>y.stationuuid!==x?.stationuuid).slice(0,7),'neighbor-row')}</div><button class="text-button" data-dest="home">К поиску и направлениям →</button>${s.queue.length?`<div class="queue-preview"><p class="eyebrow">ОЧЕРЕДЬ МАКЕТА</p>${s.queue.map(y=>`<p>${esc(y.name)}</p>`).join('')}</div>`:''}</aside></div>`;}
  function render(){ $('app').dataset.variant=s.variant;$('app').dataset.view=s.view;document.querySelectorAll('.variant-button').forEach(b=>{b.classList.toggle('selected',b.dataset.variant===s.variant);b.setAttribute('aria-pressed',b.dataset.variant===s.variant);});document.querySelectorAll('.bottom-nav [data-dest]').forEach(b=>b.classList.toggle('active',b.dataset.dest===s.view));surface.innerHTML=s.view==='feed'?feed():(s.variant==='a'?homeA():homeB());const c=$('country-filter');if(c)c.value=s.country;const t=$('category-filter');if(t)t.value=s.tag;const name=current()?.name||'Выбрать эфир';const dock=$('dock-name');if(dock)dock.textContent=name;const mobileName=$('mobile-dock-name');if(mobileName)mobileName.textContent=name;const artwork=current()?art(current()):'R';const dockArt=$('dock-art');if(dockArt)dockArt.innerHTML=artwork;const mobileArt=$('mobile-dock-art');if(mobileArt)mobileArt.innerHTML=artwork;}
  async function load(reset=true){const id=++s.request;s.loading=true;s.error='';if(reset){s.cursor='';s.items=[];}render();const p=new URLSearchParams({limit:'16'});if(s.query)p.set('q',s.query);if(s.country)p.set('country',s.country);if(s.tag)p.set('tag',s.tag);if(s.cursor)p.set('cursor',s.cursor);try{const r=await fetch(`/api/catalog/search?${p}`,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error(`Каталог ответил ${r.status}`);const data=await r.json();if(id!==s.request)return;s.items=reset?(data.items||[]):s.items.concat(data.items||[]);s.total=data.total||0;s.cursor=data.nextCursor||'';s.countries=data.facets?.countries||s.countries;if(!s.selected&&s.items.length)s.selected=s.items[0];}catch(e){if(id===s.request)s.error=e.message||'Не удалось загрузить каталог';}finally{if(id===s.request){s.loading=false;render();}}}
  function toast(message){const el=$('toast');el.textContent=message;el.hidden=false;clearTimeout(s.timer);s.timer=setTimeout(()=>el.hidden=true,2300);}
  function choose(id){const x=s.items.find(y=>y.stationuuid===id);if(x){s.selected=x;s.more=false;render();toast(`${x.name} · выбрано в макете`);}}
  function action(v){if(v==='enter-feed'){s.view='feed';render();toast('Макет · звук не запускается');return;}if(v==='next'||v==='prev'){const i=s.items.findIndex(y=>y.stationuuid===current()?.stationuuid);const n=i<0?(v==='next'?0:s.items.length-1):(v==='next'?Math.min(i+1,s.items.length-1):Math.max(i-1,0));if(s.items[n]){s.selected=s.items[n];render();toast(`${s.items[n].name} · выбрано в макете`);}return;}if(v==='refresh'||v==='retry'){void load();return;}if(v==='more-results'){void load(false);return;}if(v==='reset-search'){s.query='';s.country='';s.tag='';void load();return;}if(v==='more'){s.more=!s.more;render();return;}if(v==='listen'){toast('Макет · настоящий поток не запускается');return;}if(v==='save'){if(current()&&!s.saved.some(x=>x.stationuuid===current().stationuuid))s.saved.push(current());toast('Станция сохранена в этом макете');return;}if(v==='queue'){if(current()&&!s.queue.some(x=>x.stationuuid===current().stationuuid)){s.queue.push(current());toast('Добавлено в очередь макета');}else toast('Эфир уже в очереди');render();return;}if(v==='record'){openDialog('Запись эфира','Запись не запускается здесь. Открой существующий сценарий записи в приложении.');}}
  function openDialog(title,copy){$('dialog-title').textContent=title;$('dialog-copy').textContent=copy;$('honest-dialog').showModal();}
  document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.matches('.variant-button')){s.variant=t.dataset.variant;s.view='home';render();return;}if(t.dataset.select){choose(t.dataset.select);return;}if(t.dataset.dest==='home'||t.dataset.dest==='feed'){s.view=t.dataset.dest;render();return;}if(t.dataset.dest==='lira'||t.dataset.dest==='my'){openDialog(t.dataset.dest==='lira'?'Лира · приложение':'Моё · приложение',t.dataset.dest==='lira'?'Полноценный диалог Лиры остаётся в приложении.':'Библиотека и аккаунт остаются в приложении; макет не сохраняет данные.');return;}if(t.dataset.tag){s.tag=t.dataset.tag;s.query='';s.country='';s.view='home';void load();return;}if(t.dataset.action)action(t.dataset.action);});
  document.addEventListener('submit',e=>{if(e.target.id!=='search-form')return;e.preventDefault();s.query=new FormData(e.target).get('q').toString().trim();s.tag='';void load();});
  document.addEventListener('change',e=>{if(e.target.id==='country-filter'){s.country=e.target.value;void load();}if(e.target.id==='category-filter'){s.tag=e.target.value;void load();}});
  document.addEventListener('keydown',e=>{if(s.view!=='feed'||e.target.closest('input,select,textarea,[contenteditable="true"],dialog[open]'))return;if(e.key==='ArrowDown'){e.preventDefault();action('next');}if(e.key==='ArrowUp'){e.preventDefault();action('prev');}});
  let touchStart=null;surface.addEventListener('touchstart',e=>{const target=e.target;const point=e.changedTouches[0];if(s.view!=='feed'||!target.closest('.feed-stage')||target.closest('button,a,input,select')){touchStart=null;return;}touchStart={x:point.clientX,y:point.clientY};},{passive:true});surface.addEventListener('touchend',e=>{const point=e.changedTouches[0];if(!touchStart||!e.target.closest('.feed-stage'))return;const dx=point.clientX-touchStart.x;const dy=point.clientY-touchStart.y;touchStart=null;if(Math.abs(dy)>65&&Math.abs(dy)>Math.abs(dx)*1.2)action(dy<0?'next':'prev');},{passive:true});
  $('theme').addEventListener('change',e=>{const v=e.target.value;document.documentElement.dataset.theme=v==='dark'?'dark':'light';document.documentElement.dataset.backdrop=['aurora','sunrise'].includes(v)?v:'';});
  render();void load();
})();
